// ─────────────────────────────────────────────────────────────────────────
// MOCK ICONS — icons shared by the how-it-works product mocks (build-app,
// brand-portal, team-crm). The dashboard sidebar set (CRM, Team, Notification,
// Home, Messages, Add App, Brand, Apps + the workspace chevron) are the real
// product glyphs so the mocks read as the actual app; the rest stay light
// hand-drawn strokes. All inherit currentColor.
// ─────────────────────────────────────────────────────────────────────────

type IconProps = { className?: string };

const STROKE = {
  fill: "none",
  stroke: "currentColor",
  strokeWidth: 1.25,
  strokeLinecap: "round" as const,
  strokeLinejoin: "round" as const,
};

